let state = $('hello worker').first().json.state;
let session = state.initial_session.body;
let tool_messages = $input.first().json.tool_message_history;

// Grab the final assistant message as the summary
let summary = tool_messages.findLast(m => 
  m.role === 'assistant' && !m.tool_calls
);

// Build the OpenAI response envelope
return [{
  json: {
    id: "chatcmpl-decapod",
    object: "chat.completion",
    created: Math.floor(Date.now() / 1000),
    model: state.default_model,
    choices: [
      {
        index: 0,
        message: {
          role: "assistant",
          content: summary?.content ?? "Job complete."
        },
        finish_reason: "stop"
      }
    ],
    usage: {
      prompt_tokens: 0,
      completion_tokens: 0,
      total_tokens: 0
    }
  }
}];
